/// <summary>
/// PaffH 15.11.21
/// set attributes for a control
/// </summary>
public class NDXControlAttributes
{
    str text;
    int foregroundColor;
    int backgroundColor;
    int fontSize;
    FormColorScheme colorScheme;
    boolean initColorScheme;
    boolean isHTMLText;
    FormStringControl control;
    FormStaticTextControl controlStaticText;
    boolean isStaticTextControl;

}

Method.Source:
/// <summary>
/// PaffH 15.11.21
/// last modified: PaffH 15.08.25
/// </summary>
protected void new()
{
    text = '';
    isStaticTextControl = false;
}

/// <summary>
/// PaffH 15.11.21
/// </summary>
/// <param name = "_initType">NDXControlAttributesInitType</param>
/// <param name = "_text">str</param>
/// <returns>NDXControlAttributes</returns>
[SuppressBPWarning('BPParameterNotUsed','_text')]
public static NDXControlAttributes construct(NDXControlAttributesInitType _initType, str _text)
{
    NDXControlAttributesInitTypeAttribute attr = new NDXControlAttributesInitTypeAttribute(_initType);
    // PaffH 15.11.21: 3.param doesn't work yet
    //NDXControlAttributes instance = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(NDXControlAttributes)
    //    , attr
    //    , NDXInstantiationStrategyForClassWithArg::construct(_text));
    NDXControlAttributes instance = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(NDXControlAttributes), attr) as NDXControlAttributes;
    if (instance)
    {
        instance.parmText(_text);
    }

    return instance;
}

/// <summary>
/// PaffH 28.08.24
/// last modified: PaffH 29.08.25
/// </summary>
/// <param name = "_formStringControl">FormStringControl</param>
/// <returns>NDXControlAttributes</returns>
public static NDXControlAttributes constructFromControl(FormStringControl _formStringControl)
{
    NDXControlAttributes nDXControlAttributes = new NDXControlAttributes();
    nDXControlAttributes.control = _formStringControl;
    //nDXControlAttributes.fontSize = _formStringControl.fontSize();

    return nDXControlAttributes;
}

/// <summary>
/// PaffH 15.08.25
/// last modified: PaffH 29.08.25
/// </summary>
/// <param name = "_formStaticTextControl">FormStaticTextControl</param>
/// <returns>NDXControlAttributes</returns>
public static NDXControlAttributes constructFromFormStaticTextControl(FormStaticTextControl _formStaticTextControl)
{
    NDXControlAttributes nDXControlAttributes = new NDXControlAttributes();
    nDXControlAttributes.controlStaticText = _formStaticTextControl;
    //nDXControlAttributes.fontSize = _formStaticTextControl.fontSize();
    nDXControlAttributes.isStaticTextControl = true;

    return nDXControlAttributes;
}

/// <summary>
/// PaffH 15.11.21
/// last modified: PaffH 16.08.25
/// </summary>
/// <param name = "_text">str</param>
/// <returns>str</returns>
public str parmText(str _text = text)
{
    text = _text;
    if (isStaticTextControl)
    {
        if (controlStaticText)
        {
            controlStaticText.text(text);
        }
    }
    else
    {
        if (control)
        {
            control.text(text);
        }
    }

    return text;
}

