public int parmFontSize(int _fontSize = fontSize)
{
    int retValue;
    fontSize = _fontSize;
    if (!prmIsDefault(_fontSize))
    {
        if (isStaticTextControl)
        {
            //if (controlStaticText)
            //{
            //    controlStaticText.fontSize(fontSize);
            //}
            //retValue = controlStaticText ? controlStaticText.fontSize() : fontSize;
        }
        else
        {
            //if (control)
            //{
            //    control.fontSize(fontSize);
            //}
            //retValue = control ? control.fontSize() : fontSize;
        }
        retValue = fontSize;
    }
    return retValue;
}

/// <summary>
/// PaffH 15.11.21
/// last modified: PaffH 15.08.25
/// </summary>
/// <param name = "_foregroundColor">int</param>
/// <returns>int</returns>
public int parmForegroundColor(int _foregroundColor = foregroundColor)
{
    foregroundColor = _foregroundColor;
    if (!prmIsDefault(_foregroundColor))
    {
        if (isStaticTextControl)
        {
            if (controlStaticText)
            {
                controlStaticText.foregroundColor(foregroundColor);
            }
        }
        else
        {
            if (control)
            {
                control.foregroundColor(foregroundColor);
            }
        }
    }
    return foregroundColor;
