/// <summary>
/// PaffH 15.11.21
/// last modified: PaffH 15.08.25
/// </summary>
/// <param name = "_backgroundColor">int</param>
/// <returns>int</returns>
public int parmBackgroundColor(int _backgroundColor = backgroundColor)
{
    backgroundColor = _backgroundColor;
    if (!prmIsDefault(_backgroundColor))
    {
        if (isStaticTextControl)
        {
            if (controlStaticText)
            {
                controlStaticText.backgroundColor(backgroundColor);
            }
        }
        else
        {
            if (control)
            {
                control.backgroundColor(backgroundColor);
            }
        }
    }
