/// <summary>
/// PaffH 15.11.21
/// last modified: PaffH 15.08.25
/// </summary>
/// <param name = "_colorScheme">FormColorScheme</param>
/// <returns>FormColorScheme</returns>
public FormColorScheme parmColorScheme(FormColorScheme _colorScheme = colorScheme)
{
    if (!prmIsDefault(_colorScheme))
    {
        initColorScheme = true;
        if (isStaticTextControl)
        {
            if (controlStaticText)
            {
                controlStaticText.colorScheme(_colorScheme);
            }
        }
        else
        {
            if (control)
            {
                control.colorScheme(_colorScheme);
            }
        }
    }
    colorScheme = _colorScheme;
    return colorScheme;
}

/// <summary>
/// PaffH 15.11.21
/// </summary>
/// <param name = "_initColorScheme">boolean</param>
/// <returns>boolean</returns>
public boolean parmInitColorScheme(boolean _initColorScheme = initColorScheme)
{
    initColorScheme = _initColorScheme;
    return initColorScheme;
}

/// <summary>
/// PaffH 15.11.21
/// </summary>
/// <param name = "_isHTMLText">boolean</param>
/// <returns>boolean</returns>
public boolean parmIsHTMLText(boolean _isHTMLText = isHTMLText)
{
    isHTMLText = _isHTMLText;
    return isHTMLText;
}
